// 生成UUID的函数
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// 辅助函数：清理引号
function cleanValue(value) {
  if (typeof value === 'string') {
    // 移除开头和结尾的引号
    return value.replace(/^["']|["']$/g, '');
  }
  return value;
}

// 获取输入数据
const inputData = $input.all()[0];
const headers = inputData.json.headers || {};  // 从headers中获取参数
const files = inputData.binary;

// 根据错误信息，图片在binary.data中
let imageFile = null;
if (files && files.data) {
  imageFile = files.data;
  console.log('Found image in files.data');
} else if (files && files.image) {
  imageFile = files.image;
  console.log('Found image in files.image');
} else if (typeof $binary !== 'undefined' && $binary.data) {
  imageFile = $binary.data;
  console.log('Found image in $binary.data');
} else if (typeof $binary !== 'undefined' && $binary.image) {
  imageFile = $binary.image;
  console.log('Found image in $binary.image');
}

// 从headers中获取参数
const project_id = cleanValue(headers['project-id']);
const user_id = cleanValue(headers['user-id']);

// 验证必要参数
if (!project_id) {
  throw new Error(`Missing required header: project-id. Available headers: ${JSON.stringify(Object.keys(headers))}`);
}
if (!user_id) {
  throw new Error(`Missing required header: user-id. Available headers: ${JSON.stringify(Object.keys(headers))}`);
}
if (!imageFile) {
  throw new Error(`Missing required parameter: image file. Debug info:\nBinary keys: ${Object.keys(files || {})}\nJSON keys: ${Object.keys(inputData.json || {})}\nBody keys: ${Object.keys(inputData.json.body || {})}\n$binary available: ${typeof $binary !== 'undefined'}`);
}

// 生成任务ID
const taskId = generateUUID();
const timestamp = new Date().toISOString();

return {
  task_id: taskId,
  project_id: project_id,
  user_id: user_id,
  image_file: imageFile,
  timestamp: timestamp,
  image_filename: `images/${taskId}/original.jpg`
};

// 传递 Generate TaskID 的数据（包括二进制文件）给 Upload 节点
const generateTaskData = $node['Generate TaskID'].json;

// 返回任务数据，n8n 会自动传递二进制数据
return generateTaskData;

const visionResult = $node['Call Vision AI'].json;
const taskId = $node['Generate TaskID'].json.task_id;

const prompt = `请基于以下工业设备缺陷检测结果，生成详细的检测报告（Markdown格式）：

检测数据：
${JSON.stringify(visionResult, null, 2)}

报告要求：
1. 检测概述 - 简要说明检测的设备类型和检测时间
2. 缺陷分析 - 详细描述发现的缺陷类型、位置和严重程度
3. 风险评估 - 评估各类缺陷可能造成的影响和风险等级
4. 维护建议 - 提供具体的维护和修复建议
5. 总结 - 整体设备状态评估和后续关注要点

请使用专业的工业检测术语，确保报告的准确性和实用性。`;

return {
  prompt: prompt,
  task_id: taskId,
  model: 'deepseek-r1:1.5b',
  report_filename: `report/${taskId}/report.md`
};

const error = $input.all()[0].json.error || $input.all()[0].json;
const taskId = $node['Generate TaskID'].json?.task_id || 'unknown';

return {
  error_message: error.message || JSON.stringify(error),
  task_id: taskId,
  timestamp: new Date().toISOString()
};
